// Loads a client's podcast-monthly.json (committed, generated by scripts/podcast-monthly.mjs).
// Optional like the newsletter: when the file is missing the podcast view keeps its
// quarter-only layout. Without the Bedrock key the file still exists — it just carries
// the episode analyses as published instead of the AI-written month summary.
import { useEffect, useState } from 'react';
import type { PodcastMonthly } from '../types';

const CLIENT = (import.meta.env.VITE_CLIENT as string | undefined) || 'tybourne';

const loaders = import.meta.glob('../../clients/*/data/podcast-monthly.json');

export type PodcastMonthlyState =
  | { status: 'loading' }
  | { status: 'absent' }
  | { status: 'ready'; data: PodcastMonthly };

export function usePodcastMonthly(): PodcastMonthlyState {
  const [state, setState] = useState<PodcastMonthlyState>({ status: 'loading' });

  useEffect(() => {
    let alive = true;
    const loader = loaders[`../../clients/${CLIENT}/data/podcast-monthly.json`];
    if (!loader) {
      setState({ status: 'absent' });
      return;
    }
    loader()
      .then((mod) => {
        if (!alive) return;
        const data = ((mod as { default?: PodcastMonthly }).default ?? mod) as PodcastMonthly;
        setState({ status: 'ready', data });
      })
      .catch(() => {
        if (alive) setState({ status: 'absent' });
      });
    return () => {
      alive = false;
    };
  }, []);

  return state;
}
